// Where things are in Colin's drawing, in canvas pixels (2732x2048). Layer
// boxes come from landingLayers.json (generated by `npm run layers`); the
// rest is measured from the drawing and only changes if the drawing does.
import map from './landingLayers.json'

export const CANVAS = map.canvas
export const LAYERS = map.layers
export const hasLayer = (slug) => Boolean(LAYERS[slug])

// The sticky piano bar shows the canvas above `top`. Below it, the landing
// is a sidebar column plus a stage that uses the same x-range as the bar, so
// strings stay under their keys. Phones drop the sidebar column (it stacks
// above) but keep the sound tile, so the x-range starts further left.
const STAGE = { x: 690, w: CANVAS.w - 690 }
const STAGE_PHONE = { x: 555, w: CANVAS.w - 555 }
const buildRegions = ({ x, w }, phone) => ({
  bar: phone ? { x, y: 0, w, h: map.top } : { x: 0, y: 0, w: CANVAS.w, h: map.top },
  // strings and the character, at the top of the hall panel
  hallTop: { x, y: map.top, w, h: HALL.y + HALL.h - map.top },
  // the bridge, fog and markers, centred on the gap between the panels
  seam: { x, y: 780, w, h: 330 },
  // the desk panel and everything on it, down to the canvas bottom
  desk: { x, y: DESK_PANEL.y, w, h: CANVAS.h - DESK_PANEL.y },
})
// Columns of the landing on wide screens: sidebar | stage, as drawn
export const SIDEBAR_W = STAGE.x

// The drawn piano: white-key edges (left to right), black keys as [left,
// right], and the vertical extent of the keys and of the black keys.
export const PIANO = {
  edges: [795, 1028, 1253, 1485, 1711, 1944, 2169, 2401, 2627],
  black: [
    [975, 1068],
    [1229, 1311],
    [1667, 1752],
    [1891, 1984],
    [2125, 2204],
  ],
  top: 58,
  bottom: 403,
  blackBottom: 171,
}

// Tip of the guitar pick in the plucking pose: the character slides so this
// point lines up with the string being plucked.
export const PICK_X = 1850

// The two light panels in the frame: the hall (screen 1, which stretches to
// fill the window) and the desk panel. The gap between them is the seam the
// bridge crosses; the walk down ends as the desk panel reaches the piano.
export const HALL = { x: 690, y: 466, w: 1985, h: 470 }
export const DESK_PANEL = { x: 694, y: 991, w: 1977, h: 988 }
export const SEAM_Y = (HALL.y + HALL.h + DESK_PANEL.y) / 2
// At the top of Home the hall panel reaches up behind the piano bar's key
// labels to here (just under the piano's bottom edge), and scrolls away with
// the hall, leaving the bar itself transparent.
export const HALL_REACH_Y = 400
// The desk panel as shown: its top edge sits a little lower than drawn, so the
// water splashes under the bridge and the "!" marker stay on clear green
// instead of fading into the panel's glow; its bottom edge sits a little
// higher, so there's less empty panel under the (shifted) desk.
const DESK_FRAME_Y = 1030
const DESK_FRAME_TRIM = 40
export const DESK_FRAME = { ...DESK_PANEL, y: DESK_FRAME_Y, h: DESK_PANEL.y + DESK_PANEL.h - DESK_FRAME_Y - DESK_FRAME_TRIM }
// Everything on the desk panel sits this far below where it's drawn, so the
// shelf clears the key labels when the desk screen is under the piano bar.
export const DESK_SHIFT = 60
// The desk screen (where ↓ stops): the desk panel's top edge lands just under
// the piano, as the hall's does on screen 1, so the key labels sit on it. This
// canvas y lines up with the bar's bottom edge.
export const SCREEN_TWO_Y = DESK_FRAME_Y + (map.top - HALL_REACH_Y)
// Feet of the standing pose; the walk down measures from here.
export const FEET_Y = 905
// Feet of the pose at the desk (as shown, shifted down with the desk); the
// walk down ends here.
export const DESK_FEET_Y = LAYERS['char-front'] ? LAYERS['char-front'].y + LAYERS['char-front'].h + DESK_SHIFT : FEET_Y
// Band of fog around the bridge, between the two panels.
export const FOG = { x: 694, y: 800, w: 1977, h: 360 }
// Where the "where I live" bubble sits (above the "!" marker).
export const BUBBLE = { x: 1960, y: 700, w: 600, h: 170 }

// Built once (after HALL and DESK_PANEL exist) so callers get stable objects
const REGIONS = { wide: buildRegions(STAGE, false), phone: buildRegions(STAGE_PHONE, true) }
export const stageRegions = (phone) => (phone ? REGIONS.phone : REGIONS.wide)
